const ownersLine = (proj) => {
  if(!proj) return '';
  const names = [proj.owner||'', ...(proj.additionalOwners||[]).filter(o=>o && o.name).map(o=>o.name)].filter(Boolean);
  if(names.length<=1) return names.join('');
  const isArabicText = /[\u0600-\u06FF]/.test(names.join(''));
  return names.join(isArabicText ? ' و ' : ', ');
};
const todayISO = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const advanceDate = (dateStr, frequency) => {
  const [y,m,day]=(dateStr||todayISO()).split('-').map(Number);
  const months=frequency==='شهري'?1:frequency==='ربع سنوي'?3:frequency==='نصف سنوي'?6:12;
  const first=new Date(Date.UTC(y,m-1+months,1));
  const max=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();
  first.setUTCDate(Math.min(day,max));return first.toISOString().slice(0,10);
};
const monthKey = dateStr => (dateStr||'').slice(0,7);
const daysUntil = dateStr => dateStr?Math.round((Date.parse(dateStr+'T00:00:00Z')-Date.parse(todayISO()+'T00:00:00Z'))/86400000):null;
const expiryStatus = (dateStr, warnDays=60) => {
  const d = daysUntil(dateStr);
  if(d===null) return 'gray';
  if(d<0) return 'bad';
  if(d<=warnDays) return 'soon';
  return 'ok';
};
const expiryLabel = (dateStr, warnDays=60) => {
  const d = daysUntil(dateStr);
  if(d===null) return 'غير محدد';
  if(d<0) return 'منتهية منذ '+Math.abs(d)+' يوم';
  if(d<=warnDays) return 'تنتهي خلال '+d+' يوم';
  return 'سارية';
};
