const FINANCIAL_BUNDLE_RULES={"officeExpenses":{"fields":["amount","date","account","bankName","bankRef","vatable","payStatus","kind","month","category","vendor","vendorInvoiceNo","attachment","attachment_name","note","chequeNo","chequeDueDate"],"numbers":["amount"]},"projectCosts":{"fields":["projectId","amount","date","account","bankName","vatable","category","chequeNo","chequeDueDate","payStatus"],"numbers":["amount"]},"treasury":{"fields":["amount","date","type","account","toAccount","kind","month"],"numbers":["amount"]},"otherIncome":{"fields":["amount","category","vatable","account","date","payer","note"],"numbers":["amount"]},"advances":{"fields":["employeeId","type","mode","amount","monthlyInstallment","startMonth","date"],"numbers":["amount","monthlyInstallment"]},"govFees":{"fields":["projectId","amount","date","account","payerType","paidStatus","reimburseStatus","receiptNo","department","description","descriptionEn","note"],"numbers":["amount"]},"employees":{"fields":["baseSalary","grossSalary","hireDate"],"numbers":["baseSalary","grossSalary"]},"overtime":{"fields":["employeeId","hours","rate","date"],"numbers":["hours","rate"]},"leaves":{"fields":["employeeId","type","fromDate","toDate","days"],"numbers":["days"]},"recurringBills":{"fields":["amount","frequency","account","bankName","nextDueDate","active"],"numbers":["amount"]}};
function financialBundleControl(key,before,after,kind='update',context={}){
 if(key==='attendance'){
  if(kind==='delete')return {error:'لا يُحذف سجل الحضور نهائيًا.'};
  const paid=new Set([...(context.officeExpenses||[]),...(context.treasury||[])].filter(x=>x.kind==='رواتب'||x.kind==='دفعة راتب').map(x=>x.month));
  const dates=new Set([...Object.keys(before?.map||{}),...Object.keys(after?.map||{})]);
  return {correction:[...dates].some(day=>before?.map?.[day]!==after?.map?.[day]&&paid.has(day.slice(0,7)))};
 }
 const spec=FINANCIAL_BUNDLE_RULES[key];if(!spec)return {correction:false};
 if(kind==='delete')return {error:'لا يمكن حذف هذا السجل نهائيًا. الأرشفة لا تلغي أثر حركة مالية فعلية.'};
 const changed=k=>JSON.stringify(before?.[k])!==JSON.stringify(after?.[k]);
 const archived=r=>r?.archived===true||r?.cancelled===true;
 const posted=r=>!r?false:key==='officeExpenses'?r.payStatus!=='معلق':key==='govFees'?(r.paidStatus==='مدفوع'||r.reimburseStatus==='مسترد'||!!r.receiptNo):true;
 if(!after)return {error:'السجل غير موجود.'};
 for(const field of spec.fields.filter(f=>!spec.numbers.includes(f)))if(after[field]!=null&&typeof after[field]!=='string')return {error:'قيمة نصية غير صالحة: '+field};
 const required=spec.numbers.filter(f=>!['grossSalary','monthlyInstallment'].includes(f));
 if(required.some(f=>typeof after[f]!=='number'))return {error:'بيانات رقمية مطلوبة مفقودة.'};
 for(const field of spec.numbers){const v=after[field];if(v!==undefined&&(typeof v!=='number'||!Number.isFinite(v)))return {error:'قيمة رقمية غير صالحة: '+field};}
 if(['treasury','advances','govFees','recurringBills','otherIncome'].includes(key)&&(typeof after.amount!=='number'||after.amount<0))return {error:'أدخل مبلغًا غير سالب.'};
 if(['officeExpenses','projectCosts'].includes(key)&&typeof after.amount!=='number')return {error:'مبلغ المصروف مطلوب.'};
 if(['employees','overtime','leaves'].includes(key)&&spec.numbers.some(f=>typeof after[f]==='number'&&after[f]<0))return {error:'هذه القيمة لا تقبل رقمًا سالبًا.'};
 if(key==='advances'&&after.mode==='مقسّط'&&(!(after.monthlyInstallment>0)||after.monthlyInstallment>after.amount))return {error:'القسط يجب أن يكون موجبًا ولا يتجاوز إجمالي السلفة.'};
 if(key==='treasury'&&(!['قبض','صرف','تحويل'].includes(after.type)||!['البنك','الخزينة'].includes(after.account)||(after.type==='تحويل'&&(!['البنك','الخزينة'].includes(after.toAccount)||after.toAccount===after.account))))return {error:'راجع نوع الحركة وحسابَي التحويل؛ لا يمكن التحويل إلى الحساب نفسه.'};
 if(['archived','cancelled'].some(f=>after[f]!==undefined&&typeof after[f]!=='boolean'))return {error:'علامة الأرشفة غير صالحة.'};
 if(!archived(before)&&archived(after)&&posted(before||after)&&!['employees','recurringBills'].includes(key))return {error:'لا يمكن إلغاء الأثر المالي بالأرشفة. يلزم تصحيح موثق أو حركة مالية مستقلة.'};
 const needs=!!before&&((spec.fields.some(changed)&&posted(before))||archived(before)!==archived(after));
 if(!before&&archived(after))return {error:'لا يمكن إنشاء سجل مؤرشف.'};
 return {correction:needs||(!before&&['officeExpenses','projectCosts'].includes(key)&&after.amount<0),engineerAllowed:key==='govFees'&&!posted(before)&&!posted(after)};
}

function paymentControl(before,after,kind='update'){
  const archived=r=>r?.archived===true||r?.cancelled===true;
  const issued=r=>!!(r?.invoiceNo||r?.receiptNo);
  const net=r=>archived(r)?0:r?.status==='مدفوعة'?(r.amount||0):r?.status==='مدفوعة جزئياً'?(r.collectedAmount||0):0;
  const account=r=>r?.account||(r?.method==='نقداً'?'الخزينة':'البنك');
  const changed=k=>JSON.stringify(before?.[k])!==JSON.stringify(after?.[k]);
  if(kind==='delete')return {error:'لا يُسمح بحذف الدفعات نهائيًا. استخدم الأرشفة للدفعة غير المحصلة بسبب مسجل.'};
  if(!after||typeof after.amount!=='number'||!Number.isFinite(after.amount)||after.amount<0)return {error:'مبلغ الدفعة غير صالح.'};
  if(!['مدفوعة','مدفوعة جزئياً','معلقة','متأخرة','ملغاة'].includes(after.status))return {error:'حالة الدفعة غير صالحة.'};
  // الدفعة الملغاة (فسخ عقد) لا يجوز أن تكون محصّلة
  if(after.status==='ملغاة'&&net(after)>0)return {error:'لا يمكن إلغاء دفعة محصّلة. الإلغاء للدفعات غير المحصّلة بسبب فسخ العقد فقط.'};
  if(after.status==='مدفوعة جزئياً'&&(typeof after.collectedAmount!=='number'||!Number.isFinite(after.collectedAmount)||after.collectedAmount<=0||after.collectedAmount>after.amount))return {error:'التحصيل الجزئي يجب أن يكون موجبًا ولا يتجاوز قيمة الدفعة.'};
  if(['archived','cancelled'].some(k=>after[k]!==undefined&&typeof after[k]!=='boolean'))return {error:'علامة الأرشفة أو الإلغاء غير صالحة.'};
  const oldNet=net(before),newNet=net(after),archiveChanged=archived(before)!==archived(after);
  if(archived(after)&&(oldNet>0||newNet>0||(['مدفوعة','مدفوعة جزئياً'].includes(after.status)&&((after.status==='مدفوعة'?after.amount:after.collectedAmount)>0))))return {error:'لا يمكن أرشفة أو إلغاء دفعة محصلة. القبض الفعلي يحتاج مسارًا ماليًا مستقلًا، وليس إخفاء الدفعة.'};
  if(newNet>0&&(!before||oldNet===0)&&(!after.paidDate||!['نقداً','شيك','تحويل بنكي','بطاقة'].includes(after.method)||!['البنك','الخزينة'].includes(account(after))))return {error:'أكمل تاريخ الاستلام وطريقة الدفع وحساب القبض.'};
  if(after.receiptNo&&before?.receiptNo!==after.receiptNo&&newNet<=0)return {error:'لا يمكن إصدار سند قبض لدفعة غير محصلة.'};
  if(!before){if(archived(after))return {error:'أنشئ الدفعة كمسودة نشطة أولًا.'};return {correction:false,oldNet:0,newNet};}
  const structure=['projectId','contractId','phase','taxable','amount','label','month','date','dueDate'];
  const structural=(issued(before)||oldNet>0)&&structure.some(changed);
  const documents=['invoiceNo','receiptNo'].some(k=>before[k]&&changed(k))||(before.docSnapshot&&changed('docSnapshot'));
  const normalIncrease=newNet>oldNet&&after.amount===before.amount&&after.taxable===before.taxable&&account(before)===account(after)&&(before.method||'')===(after.method||'');
  const collection=oldNet>0&&(['status','collectedAmount','paidDate','method','refNo'].some(changed)||account(before)!==account(after))&&!normalIncrease;
  return {correction:!!(archiveChanged||structural||documents||collection),oldNet,newNet,archiveChanged};
}

const protectedFromHardDelete = (entity, r)=> {
  if(FINANCIAL_BUNDLE_RULES[entity])return true;
  if(entity==='projects' || entity==='contracts') return true;
  if(entity==='payments') return true;
  if(entity==='govFees' && r && (r.receiptNo || r.paidStatus==='مدفوع')) return true;
  return false;
};

