const incGross = (r)=> (r.amount||0) * (1 + incVatRate(r));   // المبلغ شامل الضريبة (ما يدخل الحساب فعلاً)
const incVat = (r)=> (r.amount||0) * incVatRate(r);
/* ==== الدين علينا: أي مصروف مدفوع من بنك غير WIO NITAQ يُعتبر ديناً على المكتب ==== */
const OWN_BANK = 'WIO NITAQ';
const isDebtExpense = (e)=>{
  if(!e || e.account==='الخزينة') return false;            // نقدي = فلوس المكتب، مش دين
  if(e.payStatus==='معلق') return false;                   // معلق لسه ماتدفعش → مش دين
  const bn = (e.bankName||'').trim().toUpperCase();
  if(!bn) return false;                                     // بنك غير محدد → لا يُحتسب دين
  return bn !== OWN_BANK.toUpperCase();                     // مدفوع من بنك غير WIO NITAQ = دين علينا
};
const expDebt = (e)=> isDebtExpense(e) ? expGross(e) : 0;   // شامل الضريبة = ما خرج فعلاً (مطابق للخزينة)
